const writeMode = this.mode === "workspace-write" || this.mode === "net-access";
if (writeMode && this.writeSid === void 0) throw new Error(`AclSandbox ${this.mode} requires a write SID — derive it from the workspace via workspaceWriteSid()`);
if (writeMode && this.tempDirOption === void 0) throw new Error(`AclSandbox ${this.mode} requires an explicit private temp directory or null`);

